<?php

declare(strict_types=1);

require dirname(__DIR__) . '/bootstrap.php';

// INSTALLATION-COMPLETION-SCHEMA-001 v1, sections 2-6; Gate 2 tasks 2.1/2.2.
// Public seams are InstallationCompletionSchemaMigration::apply() and the
// canonical runner. All schema manifests and expected results are test-owned.

function icsQ(string $value): string { return '`' . str_replace('`', '``', $value) . '`'; }
function icsDb(string $name): mysqli {
    $db = new mysqli(getenv('FMONITOR_TEST_DB_HOST') ?: '127.0.0.1', getenv('FMONITOR_TEST_DB_ADMIN_USER') ?: 'root', getenv('FMONITOR_TEST_DB_ADMIN_PASSWORD') ?: 'fmonitor2_test_root_local', $name, (int) (getenv('FMONITOR_TEST_DB_PORT') ?: 23306));
    $db->set_charset('utf8mb4');
    return $db;
}
/** @return array<string,mixed> */
function icsApply(mysqli $db, string $prefix): array {
    $class = 'FMonitor2\\InstallationProcess\\InstallationCompletionSchemaMigration';
    if (!class_exists($class)) throw new TestFailure('RED: approved public InstallationCompletionSchemaMigration v10 seam is missing.');
    return $class::apply($db, $prefix);
}
/** @return array{exit:int,out:string,err:string} */
function icsRunner(string $name, string $prefix, bool $unreachable = false): array {
    $env = ['FMONITOR_DB_HOST'=>$unreachable?'127.0.0.1':(getenv('FMONITOR_TEST_DB_HOST')?:'127.0.0.1'),'FMONITOR_DB_PORT'=>$unreachable?'1':(string)(getenv('FMONITOR_TEST_DB_PORT')?:23306),'FMONITOR_DB_NAME'=>$unreachable?'not_accessed':$name,'FMONITOR_DB_USER'=>$unreachable?'not_accessed':(getenv('FMONITOR_TEST_DB_ADMIN_USER')?:'root'),'FMONITOR_DB_PASSWORD'=>$unreachable?'secret':(getenv('FMONITOR_TEST_DB_ADMIN_PASSWORD')?:'fmonitor2_test_root_local'),'FMONITOR_PROCESS_TABLE_PREFIX'=>$prefix];
    $cmd = array_merge(['env'], array_map(fn($k,$v)=>"$k=$v", array_keys($env), $env), [PHP_BINARY, dirname(__DIR__,2).'/bin/fmonitor2-migrate.php']);
    $p=proc_open($cmd,[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes,dirname(__DIR__,2));
    if(!is_resource($p)) throw new TestFailure('SETUP_FAILURE: runner start');
    fclose($pipes[0]);$out=(string)stream_get_contents($pipes[1]);$err=(string)stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);
    return ['exit'=>proc_close($p),'out'=>$out,'err'=>$err];
}
function icsCreateRoot(mysqli $db,string $prefix,string $collation='utf8mb4_unicode_ci'):void {
    $db->query('CREATE TABLE '.icsQ($prefix.'fm2_pilot_completion_facts')."(id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,installation_case_id BIGINT UNSIGNED NOT NULL,fact_type ENUM('pto_act','declaration') NOT NULL,fact_date DATE NOT NULL,details VARCHAR(500) NOT NULL DEFAULT '',recorded_at VARCHAR(40) NOT NULL,recorded_by_user_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(id),UNIQUE KEY uq_case_fact(installation_case_id,fact_type),KEY installation_case_id(installation_case_id,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=$collation");
}
function icsCreateRawCorrections(mysqli $db,string $prefix,string $collation='utf8mb4_unicode_ci'):void {
    $root=icsQ($prefix.'fm2_pilot_completion_facts');$table=icsQ($prefix.'fm2_pilot_completion_fact_corrections');
    $db->query("CREATE TABLE $table(id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,root_fact_id BIGINT UNSIGNED NOT NULL,version_no INT UNSIGNED NOT NULL,previous_correction_id BIGINT UNSIGNED DEFAULT NULL,previous_version_no INT UNSIGNED DEFAULT NULL,fact_date DATE NOT NULL,reason VARCHAR(1000) NOT NULL,recorded_at VARCHAR(40) NOT NULL,recorded_by_user_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(id),UNIQUE KEY uq_root_version(root_fact_id,version_no),UNIQUE KEY uq_previous_correction(previous_correction_id),UNIQUE KEY uq_correction_identity(id,root_fact_id,version_no),KEY root_history(root_fact_id,id),CONSTRAINT fk_completion_correction_root FOREIGN KEY(root_fact_id) REFERENCES $root(id),CONSTRAINT fk_completion_correction_previous FOREIGN KEY(previous_correction_id,root_fact_id,previous_version_no) REFERENCES $table(id,root_fact_id,version_no),CHECK(version_no>=1),CHECK((version_no=1 AND previous_correction_id IS NULL AND previous_version_no IS NULL) OR (version_no>1 AND previous_correction_id IS NOT NULL AND previous_version_no=version_no-1)),CHECK(char_length(trim(reason)) BETWEEN 1 AND 1000)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=$collation");
}
function icsNormalizeCorrections(mysqli$db,string$prefix):void{$incoming=icsForeignKeyChecks($db);try{$db->query('SET SESSION FOREIGN_KEY_CHECKS=0');$db->query('ALTER TABLE '.icsQ($prefix.'fm2_pilot_completion_fact_corrections').' DROP INDEX fk_completion_correction_previous');}finally{$db->query('SET SESSION FOREIGN_KEY_CHECKS='.$incoming);}}
function icsCreateCorrections(mysqli$db,string$prefix,string$collation='utf8mb4_unicode_ci'):void{icsCreateRawCorrections($db,$prefix,$collation);icsNormalizeCorrections($db,$prefix);}
/** @return array<string,mixed> */
function icsState(mysqli$db,string$prefix):array {
    $out=[];foreach(['fm2_pilot_completion_facts','fm2_pilot_completion_fact_corrections']as$base){$name=$prefix.$base;$e=$db->real_escape_string($name);$table=$db->query("SELECT ENGINE,TABLE_COLLATION,AUTO_INCREMENT FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='$e'")->fetch_assoc();if(!$table){$out[$name]=null;continue;}$out[$name]=['table'=>$table,'columns'=>$db->query("SELECT COLUMN_NAME,COLUMN_TYPE,IS_NULLABLE,COLUMN_DEFAULT,EXTRA,IS_GENERATED,GENERATION_EXPRESSION,CHARACTER_SET_NAME,COLLATION_NAME FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='$e' ORDER BY ORDINAL_POSITION")->fetch_all(MYSQLI_ASSOC),'indexes'=>$db->query("SELECT INDEX_NAME,NON_UNIQUE,SEQ_IN_INDEX,COLUMN_NAME,SUB_PART,COLLATION,INDEX_TYPE,IGNORED FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='$e' ORDER BY BINARY INDEX_NAME,SEQ_IN_INDEX")->fetch_all(MYSQLI_ASSOC),'constraints'=>$db->query("SELECT tc.CONSTRAINT_NAME,tc.CONSTRAINT_TYPE,cc.CHECK_CLAUSE,kcu.REFERENCED_TABLE_NAME,kcu.REFERENCED_COLUMN_NAME FROM information_schema.TABLE_CONSTRAINTS tc LEFT JOIN information_schema.CHECK_CONSTRAINTS cc ON cc.CONSTRAINT_SCHEMA=tc.CONSTRAINT_SCHEMA AND cc.TABLE_NAME=tc.TABLE_NAME AND cc.CONSTRAINT_NAME=tc.CONSTRAINT_NAME LEFT JOIN information_schema.KEY_COLUMN_USAGE kcu ON kcu.CONSTRAINT_SCHEMA=tc.CONSTRAINT_SCHEMA AND kcu.TABLE_NAME=tc.TABLE_NAME AND kcu.CONSTRAINT_NAME=tc.CONSTRAINT_NAME WHERE tc.CONSTRAINT_SCHEMA=DATABASE() AND tc.TABLE_NAME='$e' ORDER BY BINARY tc.CONSTRAINT_NAME,kcu.ORDINAL_POSITION")->fetch_all(MYSQLI_ASSOC),'rows'=>$db->query('SELECT * FROM '.icsQ($name).' ORDER BY id')->fetch_all(MYSQLI_ASSOC)];}return$out;
}
function icsExpectFailure(mysqli$db,string$sql,string$label):void{$before=icsState($db,'chain_');try{$db->query($sql);throw new TestFailure("$label accepted");}catch(mysqli_sql_exception){}assertSameValue($before,icsState($db,'chain_'),"$label leaves accepted history byte-exact");}
function icsForeignKeyChecks(mysqli$db):int{return(int)$db->query('SELECT @@SESSION.FOREIGN_KEY_CHECKS value')->fetch_assoc()['value'];}
function icsNorm(string$v):string{$v=strtolower(str_replace([" ","\n","\r","\t",'`'],'',$v));while(strlen($v)>1&&$v[0]==='('&&$v[-1]===')'){$d=0;$all=true;for($i=0;$i<strlen($v);$i++){if($v[$i]==='(')$d++;elseif($v[$i]===')')$d--;if($d===0&&$i<strlen($v)-1){$all=false;break;}}if(!$all)break;$v=substr($v,1,-1);}return$v;}
function icsConstraint(mysqli$db,string$table,string$type,int$offset=0):string{$e=$db->real_escape_string($table);$rows=$db->query("SELECT CONSTRAINT_NAME FROM information_schema.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE()AND TABLE_NAME='$e' AND CONSTRAINT_TYPE='$type' ORDER BY BINARY CONSTRAINT_NAME")->fetch_all(MYSQLI_ASSOC);return(string)$rows[$offset]['CONSTRAINT_NAME'];}
function icsDropFamily(mysqli$db,string$p):void{$db->query('DROP TABLE IF EXISTS '.icsQ($p.'fm2_pilot_completion_fact_corrections'));$db->query('DROP TABLE IF EXISTS '.icsQ($p.'fm2_pilot_completion_facts'));}
function icsConflictCase(mysqli$db,string$p,string$member,callable$mutate,string$label):void{try{icsCreateRoot($db,$p);$fkMutation=$member==='correction';$fkMutation?icsCreateRawCorrections($db,$p):icsCreateCorrections($db,$p);$mutate($db,$p);if($fkMutation)icsNormalizeCorrections($db,$p);$before=icsState($db,$p);$table=$p.($member==='root'?'fm2_pilot_completion_facts':'fm2_pilot_completion_fact_corrections');assertSameValue(['applied'=>false,'schemaVersion'=>10,'reason'=>'SCHEMA_MIGRATION_CONFLICT','conflictingTables'=>[$table]],icsApply($db,$p),"$label exact conflict");assertSameValue($before,icsState($db,$p),"$label preserves rows/schema/AUTO_INCREMENT with zero repair");}finally{icsDropFamily($db,$p);$db->query('DROP TABLE IF EXISTS '.icsQ($p.'decoy_roots'));}}
function icsAssertFinal(mysqli$db,string$p,string$collation='utf8mb4_unicode_ci'):void{$s=icsState($db,$p);$root=$s[$p.'fm2_pilot_completion_facts'];$corr=$s[$p.'fm2_pilot_completion_fact_corrections'];$cm=fn($c)=>implode('|',[$c['COLUMN_NAME'],$c['COLUMN_TYPE'],$c['IS_NULLABLE'],$c['COLUMN_DEFAULT']===null?'NULL':$c['COLUMN_DEFAULT'],$c['EXTRA'],$c['IS_GENERATED'],$c['GENERATION_EXPRESSION']===null?'NULL':$c['GENERATION_EXPRESSION'],$c['CHARACTER_SET_NAME']??'NULL',$c['COLLATION_NAME']??'NULL']);$im=fn($i)=>implode('|',[$i['INDEX_NAME'],$i['NON_UNIQUE'],$i['SEQ_IN_INDEX'],$i['COLUMN_NAME'],$i['SUB_PART']===null?'NULL':$i['SUB_PART'],$i['COLLATION'],$i['INDEX_TYPE'],$i['IGNORED']]);assertSameValue(['id|bigint(20) unsigned|NO|NULL|auto_increment|NEVER|NULL|NULL|NULL','installation_case_id|bigint(20) unsigned|NO|NULL||NEVER|NULL|NULL|NULL',"fact_type|enum('pto_act','declaration')|NO|NULL||NEVER|NULL|utf8mb4|$collation",'fact_date|date|NO|NULL||NEVER|NULL|NULL|NULL',"details|varchar(500)|NO|''||NEVER|NULL|utf8mb4|$collation","recorded_at|varchar(40)|NO|NULL||NEVER|NULL|utf8mb4|$collation",'recorded_by_user_id|bigint(20) unsigned|NO|NULL||NEVER|NULL|NULL|NULL'],array_map($cm,$root['columns']),'complete root column manifest');assertSameValue(['id|bigint(20) unsigned|NO|NULL|auto_increment|NEVER|NULL|NULL|NULL','root_fact_id|bigint(20) unsigned|NO|NULL||NEVER|NULL|NULL|NULL','version_no|int(10) unsigned|NO|NULL||NEVER|NULL|NULL|NULL','previous_correction_id|bigint(20) unsigned|YES|NULL||NEVER|NULL|NULL|NULL','previous_version_no|int(10) unsigned|YES|NULL||NEVER|NULL|NULL|NULL','fact_date|date|NO|NULL||NEVER|NULL|NULL|NULL',"reason|varchar(1000)|NO|NULL||NEVER|NULL|utf8mb4|$collation","recorded_at|varchar(40)|NO|NULL||NEVER|NULL|utf8mb4|$collation",'recorded_by_user_id|bigint(20) unsigned|NO|NULL||NEVER|NULL|NULL|NULL'],array_map($cm,$corr['columns']),'complete corrections column manifest');assertSameValue(['PRIMARY|0|1|id|NULL|A|BTREE|NO','installation_case_id|1|1|installation_case_id|NULL|A|BTREE|NO','installation_case_id|1|2|id|NULL|A|BTREE|NO','uq_case_fact|0|1|installation_case_id|NULL|A|BTREE|NO','uq_case_fact|0|2|fact_type|NULL|A|BTREE|NO'],array_map($im,$root['indexes']),'complete root index manifest');assertSameValue(['PRIMARY|0|1|id|NULL|A|BTREE|NO','root_history|1|1|root_fact_id|NULL|A|BTREE|NO','root_history|1|2|id|NULL|A|BTREE|NO','uq_correction_identity|0|1|id|NULL|A|BTREE|NO','uq_correction_identity|0|2|root_fact_id|NULL|A|BTREE|NO','uq_correction_identity|0|3|version_no|NULL|A|BTREE|NO','uq_previous_correction|0|1|previous_correction_id|NULL|A|BTREE|NO','uq_root_version|0|1|root_fact_id|NULL|A|BTREE|NO','uq_root_version|0|2|version_no|NULL|A|BTREE|NO'],array_map($im,$corr['indexes']),'complete corrections index manifest');assertSameValue("InnoDB:$collation",$root['table']['ENGINE'].':'.$root['table']['TABLE_COLLATION'],'root engine/collation');assertSameValue("InnoDB:$collation",$corr['table']['ENGINE'].':'.$corr['table']['TABLE_COLLATION'],'correction engine/collation');$rootDomain=array_values(array_filter($root['constraints'],fn($c)=>in_array($c['CONSTRAINT_TYPE'],['FOREIGN KEY','CHECK'],true)));assertSameValue([],$rootDomain,'root has no FK/CHECK constraints');$table=$db->real_escape_string($p.'fm2_pilot_completion_fact_corrections');$fks=$db->query("SELECT rc.CONSTRAINT_NAME,kcu.ORDINAL_POSITION,kcu.COLUMN_NAME,kcu.REFERENCED_TABLE_NAME,kcu.REFERENCED_COLUMN_NAME,rc.UPDATE_RULE,rc.DELETE_RULE FROM information_schema.REFERENTIAL_CONSTRAINTS rc JOIN information_schema.KEY_COLUMN_USAGE kcu ON kcu.CONSTRAINT_SCHEMA=rc.CONSTRAINT_SCHEMA AND kcu.CONSTRAINT_NAME=rc.CONSTRAINT_NAME AND kcu.TABLE_NAME=rc.TABLE_NAME WHERE rc.CONSTRAINT_SCHEMA=DATABASE()AND rc.TABLE_NAME='$table' ORDER BY BINARY rc.CONSTRAINT_NAME,kcu.ORDINAL_POSITION")->fetch_all(MYSQLI_ASSOC);assertSameValue(["fk_completion_correction_previous|1|previous_correction_id|{$p}fm2_pilot_completion_fact_corrections|id|RESTRICT|RESTRICT","fk_completion_correction_previous|2|root_fact_id|{$p}fm2_pilot_completion_fact_corrections|root_fact_id|RESTRICT|RESTRICT","fk_completion_correction_previous|3|previous_version_no|{$p}fm2_pilot_completion_fact_corrections|version_no|RESTRICT|RESTRICT","fk_completion_correction_root|1|root_fact_id|{$p}fm2_pilot_completion_facts|id|RESTRICT|RESTRICT"],array_map(fn($x)=>implode('|',array_values($x)),$fks),'exact named ordered FK identities/actions');$checks=[];foreach($corr['constraints']as$c)if($c['CONSTRAINT_TYPE']==='CHECK')$checks[]=icsNorm((string)$c['CHECK_CLAUSE']);sort($checks,SORT_STRING);$expected=['char_length(trim(reason))between1and1000','version_no>=1','version_no=1andprevious_correction_idisnullandprevious_version_noisnullorversion_no>1andprevious_correction_idisnotnullandprevious_version_no=version_no-1'];sort($expected,SORT_STRING);assertSameValue($expected,$checks,'exact normalized three CHECK identities');}

